package pe.edu.upeu.pago.client; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Component; import org.springframework.web.client.RestClient; import pe.edu.upeu.pago.dto.CursoCompraDto; @Component @RequiredArgsConstructor public class CursoClient { private final RestClient.Builder builder; public CursoCompraDto obtener(Long id){return builder.build().get().uri("http://kido-curso-ms/internal/v1/cursos/{id}/resumen-compra",id).retrieve().body(CursoCompraDto.class);} }